import{_ as s,a0 as i,w as l,s as u,ao as r,I as n,x as p,a1 as t,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"在Linux上如何清除內存的 Cache、Buffer 和交換空間 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上如何清除內存的 Cache、Buffer 和交換空間 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上如何清除內存的 Cache、Buffer 和交換空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上如何清除內存的 Cache、Buffer 和交換空間 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux","title":"在Linux上如何清除內存的 Cache、Buffer 和交換空間","tag":"201506","desc":""},"relativePath":"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux.md","filePath":"[post].md"}'),c={name:"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux.md"};function d(f,e,m,h,C,x){const a=i("Link");return l(),u("div",null,[e[19]||(e[19]=r(`<h1 id="在linux上如何清除內存的-cache、buffer-和交換空間" tabindex="-1">在Linux上如何清除內存的 Cache、Buffer 和交換空間 <a class="header-anchor" href="#在linux上如何清除內存的-cache、buffer-和交換空間" aria-label="Permalink to “在Linux上如何清除內存的 Cache、Buffer 和交換空間”">​</a></h1><p>像任何其他的操作系統一樣，GNU/Linux 已經實現的內存管理不僅有效，而且更好。但是，如果有任何進程正在蠶食你的內存，而你想要清除它的話，Linux 提供了一個刷新或清除RAM緩存方法。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Clear-RAM-Cache-in-Linux.jpg" alt="Clear RAM Cache and Swap in Linux"></p><h3 id="如何在-linux-中清除緩存-cache" tabindex="-1">如何在 Linux 中清除緩存（Cache）？### <a class="header-anchor" href="#如何在-linux-中清除緩存-cache" aria-label="Permalink to “如何在 Linux 中清除緩存（Cache）？###”">​</a></h3><p>每個 Linux 系統有三種選項來清除緩存而不需要中斷任何進程或服務。</p><p>（LCTT 譯註：Cache，譯作“緩存”，指 CPU 和內存之間高速緩存。Buffer，譯作“緩衝區”，指在寫入磁盤前的存儲再內存中的內容。在本文中，Buffer 和 Cache 有時候會通指。）</p><ol><li><p>僅清除頁面緩存（PageCache）</p><pre><code> # sync; echo 1 &gt; /proc/sys/vm/drop_caches		
</code></pre></li><li><p>清除目錄項和inode</p><pre><code> # sync; echo 2 &gt; /proc/sys/vm/drop_caches		
</code></pre></li><li><p>清除頁面緩存，目錄項和inode</p><pre><code> # sync; echo 3 &gt; /proc/sys/vm/drop_caches 
</code></pre></li></ol><p>上述命令的説明：</p>`,8)),n("p",null,[e[1]||(e[1]=p("sync 將刷新文件系統緩衝區（buffer），命令通過“;”分隔，順序執行，shell在執行序列中的下一個命令之前會等待命令的終止。正如內核文檔中提到的，寫入到drop_cache將清空緩存而不會殺死任何應用程序/服務，",-1)),t(a,{href:"https://linux.cn/article-3592-1.html"},{default:o(()=>[...e[0]||(e[0]=[p("echo命令",-1)])]),_:1}),e[2]||(e[2]=p("做寫入文件的工作。",-1))]),e[20]||(e[20]=r(`<p>如果你必須清除磁盤高速緩存，第一個命令在企業和生產環境中是最安全，<code>&quot;...echo 1&gt; ...&quot;</code>只會清除頁面緩存。 在生產環境中不建議使用上面的第三個選項<code>&quot;...echo 3 &gt; ...&quot;</code> ，除非你明確自己在做什麼，因為它會清除緩存頁，目錄項和inodes。</p><p><strong>在Linux上釋放也許被內核所使用的緩衝區（Buffer）和緩存（Cache）是否是個好主意？</strong></p><p>當你設置許多設定想要檢查效果時，如果它實際上是專門針對 I/O 範圍的基準測試，那麼你可能需要清除緩衝區和緩存。你可以如上所示刪除緩存，無需重新啓動系統（即無需停機）。</p><p>Linux被設計成它在尋找磁盤之前到磁盤緩存尋找的方式。如果它發現該資源在緩存中，則該請求不會發送到磁盤。如果我們清理緩存，磁盤緩存就起不到作用了，系統會到磁盤上尋找資源。</p><p>此外，當清除緩存後它也將減慢系統運行速度，系統會將每一個被請求的資源再次加載到磁盤緩存中。</p><p>現在，我們將創建一個 shell 腳本，通過一個 cron 調度任務在每天下午2點自動清除RAM緩存。如下創建一個 shell 腳本 clearcache.sh 並在其中添加以下行：</p><pre><code>#!/bin/bash
# 注意，我們這裏使用了 &quot;echo 3&quot;，但是不推薦使用在產品環境中，應該使用 &quot;echo 1&quot;
echo &quot;echo 3 &amp;gt; /proc/sys/vm/drop_caches&quot;
</code></pre><p>給clearcache.sh文件設置執行權限</p><pre><code># chmod 755 clearcache.sh
</code></pre><p>現在，當你需要清除內存緩存時只需要調用腳本。</p><p>現在設置一個每天下午2點的定時任務來清除RAM緩存，打開crontab進行編輯。</p><pre><code># crontab -e
</code></pre><p>添加以下行，保存並退出。</p><pre><code>0 3 * * * /path/to/clearcache.sh
</code></pre>`,14)),n("p",null,[e[4]||(e[4]=p("有關如何創建一個定時任務，更多細節你可以查看我們的文章 ",-1)),t(a,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:o(()=>[...e[3]||(e[3]=[p("11 個定時調度任務的例子",-1)])]),_:1}),e[5]||(e[5]=p("。",-1))]),e[21]||(e[21]=r(`<p><strong>在生產環境的服務器上自動清除RAM是否是一個好主意？</strong></p><p>不！它不是。想想一個情況，當你已經預定腳本在每天下午2點來清除內存緩存。那麼其時該腳本會執行並刷新你的內存緩存。在某一天由於某些原因，可能您的網站的在線用户會超過預期地從你的服務器請求資源。</p><p>而在這時，按計劃調度的腳本運行了，並清除了緩存中的一切。當所有的用户都從磁盤讀取數據時，這將導致服務器崩潰並損壞資料庫。因此，清除緩存僅在必要時並且在你的預料之中，否則你就是個呆瓜系統管理員。</p><p>###如何清除Linux的交換空間？###</p><p>如果你想清除掉的空間，你可以運行下面的命令：</p><pre><code># swapoff -a &amp;&amp; swapon -a
</code></pre><p>此外，瞭解有關風險後，您可以將上面的命令添加到cron中。</p><p>現在，我們將上面兩種命令結合成一個命令，寫成正確的腳本來同時清除RAM緩存和交換空間。</p><pre><code># echo 3 &gt; /proc/sys/vm/drop_caches &amp;&amp; swapoff -a &amp;&amp; swapon -a &amp;&amp; printf &#39;\\n%s\\n&#39; &#39;Ram-cache and Swap Cleared&#39;
</code></pre><p>或</p><pre><code>su -c &#39;echo 3 &gt; /proc/sys/vm/drop_caches&#39; &amp;&amp; swapoff -a &amp;&amp; swapon -a &amp;&amp; printf &#39;\\n%s\\n&#39; &#39;Ram-cache and Swap Cleared&#39;
</code></pre><p>在測試上面的命令之前，我們在執行腳本前後運行“free -m” 來檢查緩存。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Clear-RAM-Cache.gif" alt="Clear RAM Cache and Swap Space"></p><p>就是這樣，如果你喜歡這篇文章，不要忘記向我們提供您寶貴的意見，讓我們知道，您認為在企業和生產環境中清除內存緩存和緩衝區是否是一個好主意？</p><hr>`,15)),n("p",null,[e[7]||(e[7]=p("via: ",-1)),t(a,{href:"http://www.tecmint.com/clear-ram-memory-cache-buffer-and-swap-space-on-linux/"},{default:o(()=>[...e[6]||(e[6]=[p("http://www.tecmint.com/clear-ram-memory-cache-buffer-and-swap-space-on-linux/",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=p("作者：",-1)),t(a,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[8]||(e[8]=[p("Avishek Kumar",-1)])]),_:1}),e[12]||(e[12]=p(" 譯者：",-1)),t(a,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...e[9]||(e[9]=[p("strugglingyouth",-1)])]),_:1}),e[13]||(e[13]=p(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[10]||(e[10]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[16]||(e[16]=p("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[14]||(e[14]=[p("LCTT",-1)])]),_:1}),e[17]||(e[17]=p(" 原創翻譯，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...e[15]||(e[15]=[p("Linux中國",-1)])]),_:1}),e[18]||(e[18]=p(" 榮譽推出",-1))])])}const g=s(c,[["render",d]]);export{_ as __pageData,g as default};
